  mnemonic:{word:"Kernig = Knee, Brudzinski = Bend neck", items:[["Kernig","Extending the knee with hip flexed causes pain and resistance"],["Brudzinski","Flexing the neck causes hips and knees to flex"]], extra:"Both indicate meningeal irritation."},
  example:"A 19-year-old engineering student from Vellore recovers from viral meningitis but tires after 10 minutes of walking. The physio plans a graded walking programme starting at 10 minutes daily, increasing gradually, and advises a phased return to classes.",
